import openpyxl

path='mimotable_batch1_0294_template_8159_input.xlsx'
wb = openpyxl.load_workbook(path, data_only=False)
ws = wb['Sheet1']
print('dims', ws.dimensions)
# count formulas
fcount=0
dcount=0
for row in ws.iter_rows(min_row=1, max_row=10, min_col=1, max_col=15):
    for cell in row:
        if cell.value is not None:
            if cell.data_type == 'f':
                fcount+=1
            else:
                dcount+=1
print('formula cells', fcount, 'non-empty non-formula', dcount)
# print all cells
for r in range(1, 11):
    for c in range(1, 16):
        cell=ws.cell(row=r, column=c)
        if cell.value is not None:
            print(cell.coordinate, repr(cell.value))
print('--- cached values ---')
wb2 = openpyxl.load_workbook(path, data_only=True)
ws2 = wb2['Sheet1']
for r in range(3, 11):
    print(r, [ws2.cell(row=r, column=col).value for col in range(2,16)])
